import{_ as t,C as r,o as i,c as l,E as s,a2 as n}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"技能更小，不等于还是同一个技能","description":"","frontmatter":{"title":"技能更小，不等于还是同一个技能","date":"2026-09-02","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"压缩或动态改写后的技能包要继续沿用原能力身份，必须保持哪些不变量？","summary":"一项技能压缩研究报告了受保护压缩下的显著令牌缩减，也报告了激进配置下的明显损失。工程结论不只是少压缩：渐进加载技能需要为公共入口、路由、资源边界与行为保留版本绑定的证据。","sources":["research/analysis/Q-20260902-03-skill-compression-routing-contract.md"],"item_id":"Q-20260902-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-02-a-smaller-skill-is-not-the-same-skill-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md","filePath":"zh/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md","lastUpdated":1788361073000}'),o={name:"zh/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md"};function p(h,e,c,d,m,u){const a=r("ArticleCover");return i(),l("div",null,[s(a,{image:"/assets/covers/daily-2026-09-02-a-smaller-skill-is-not-the-same-skill-cover.png",kicker:"开源工程 · 每日研究",title:"技能更小，不等于还是同一个技能",summary:"一项技能压缩研究报告了受保护压缩下的显著令牌缩减，也报告了激进配置下的明显损失。工程结论不只是少压缩：渐进加载技能需要为公共入口、路由、资源边界与行为保留版本绑定的证据。",version:"Q-20260902-03",status:"Daily Runtime V5 · 2026-09-02",languageHref:"/en/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="技能更小-不等于还是同一个技能" tabindex="-1">技能更小，不等于还是同一个技能 <a class="header-anchor" href="#技能更小-不等于还是同一个技能" aria-label="Permalink to &quot;技能更小，不等于还是同一个技能&quot;">​</a></h1><p>一次压缩删除了重复说明并缩短引用。所有文件仍在包内，根入口也能加载，令牌数量明显下降；但一个公共子技能无法再被独立调用，另一份条件资源被错误路由加载。技能包更小了，它还是原来的能力吗？</p><p>对于渐进加载技能，文件存在并不足够。技能包更像一张带路由的图：根指令只在执行路径需要时选择引用、模式、脚本、资产与嵌套子技能。压缩可以保留可见目录，同时改变使它可执行的路径。</p><p>该一手研究对受保护压缩给出积极结果，也给出激进优化的警告。在其内容审核评测中，受保护方法报告减少约 38% 的技能包令牌和 10.4% 的端到端单次运行令牌，且未报告质量损失；在一个多入口包上，它报告公共入口与路由近乎完全保留。相比之下，不受保护的 71% 激进配置通过单边假阳性造成最高 26 个准确率百分点的损失。</p><p>这些是作者报告的结果，不是独立验证。其有边界的工程结论仍然清楚：<strong>压缩后的技能只有在新版本上重新建立结构与行为契约证据，才能继续沿用旧能力身份。</strong></p><h2 id="技能包是一张路由图" tabindex="-1">技能包是一张路由图 <a class="header-anchor" href="#技能包是一张路由图" aria-label="Permalink to &quot;技能包是一张路由图&quot;">​</a></h2><p>扁平提示词优化只问大致相同的说明是否还在。渐进加载提出更强的问题：每个公共入口能否继续独立调用；必要路由是否到达预期资源；私有、公共和条件资源的分类是否仍成立；去重所依赖的环境假设是否适合目标运行时。</p><p>根技能可以通过冒烟测试，而公共子技能仍然失败。引用文件可以留在目录里，却无法在原条件下被选中。脚本可以通过新路由到达，却收到不同输入或权限。即使文件差异看起来温和，这些都属于契约变化。</p><p>因此，技能身份不仅包含文字，还包含可调用入口、路由规则、可见性边界、环境假设，以及把源包连接到候选版本的来源链。</p><h2 id="数字只支持有边界的结论" tabindex="-1">数字只支持有边界的结论 <a class="header-anchor" href="#数字只支持有边界的结论" aria-label="Permalink to &quot;数字只支持有边界的结论&quot;">​</a></h2><p>受保护结果说明，在论文报告的设置中，显著压缩与路由保留可以并存。它没有建立通用安全比例。约 38% 的包令牌下降和 10.4% 的单次运行下降描述的是一个评测系统，不是所有包都能采用的阈值。</p><p>激进案例的重要性在于损害具有不对称性。71% 配置不只是降低平均分；论文报告单边假阳性使准确率最多下降 26 个百分点。可用性检查或令牌指标都看不到这种失败分布。</p><p>所以压缩率是优化指标，不是准入标准。真正的问题是哪些契约表面被保留，以及当前版本中有什么证据支持这一主张。</p><h2 id="结构保留需要显式证据" tabindex="-1">结构保留需要显式证据 <a class="header-anchor" href="#结构保留需要显式证据" aria-label="Permalink to &quot;结构保留需要显式证据&quot;">​</a></h2><p>最低结构契约包括公共可调用入口、内部路由可达性、资源可见性、环境假设与来源。</p><p>公共入口需要稳定身份和独立可达性；必要内部路径必须解析到预期资源；私有、公共和条件材料要保持原访问与加载边界；被删除的重复内容必须由目标环境真实提供。新候选还应记录源哈希、变换、候选哈希、审计结果与采用决定。</p><p>证据必须绑定到实际生成的版本。后续写入时压缩变更不能因为目录名相同或拥有共同祖先，就继承前一版本的审计。每次改写都生成新的候选和新的证据边界。</p><h2 id="路由正确是必要条件-不是充分条件" tabindex="-1">路由正确是必要条件，不是充分条件 <a class="header-anchor" href="#路由正确是必要条件-不是充分条件" aria-label="Permalink to &quot;路由正确是必要条件，不是充分条件&quot;">​</a></h2><p>完整的路由审计证明节点仍可到达，却不能证明到达的脚本语义相同、权限要求不变，或外部效果仍安全。</p><p>静态路由检查与任务级评测回答不同问题。结构审计确认入口与路径；行为测试抽样输出、错误分布与环境兼容性；权限和副作用检查验证技能声称保留的权限与效果契约。</p><p>因此，“压缩过程免评测”不能被读成“采用过程免验证”。压缩器可以避免每次内部修改都运行完整基准，但治理流程在激活新版本前仍需有边界的证据。</p><h2 id="采用候选-不要原地重写身份" tabindex="-1">采用候选，不要原地重写身份 <a class="header-anchor" href="#采用候选-不要原地重写身份" aria-label="Permalink to &quot;采用候选，不要原地重写身份&quot;">​</a></h2><p>更安全的生命周期把优化输出视为暂存候选。系统记录不可变源版本与变换，审计公共入口和路由，运行与风险匹配的行为检查，然后作出显式采用决定。</p><p>回滚目标应是先前已采用的精确包身份，而不是重建近似版本。采用后若发现漏掉路由、不对称错误、权限漂移或环境不匹配，运行时可恢复上一个精确工件，并保留失败候选用于分析。</p><p>验证深度应与主张匹配。只含文档的资源可能只需结构与渲染检查；能够写数据或调用外部工具的技能还需要权限、错误与效果边界证据。令牌节省从来不会扩大证据能够授权的范围。</p><h2 id="证据边界仍然很窄" tabindex="-1">证据边界仍然很窄 <a class="header-anchor" href="#证据边界仍然很窄" aria-label="Permalink to &quot;证据边界仍然很窄&quot;">​</a></h2><p>论文报告的是选定技能包与特定工业多轮评测。它没有独立证明任意技能与插件的完整语义等价、权限保留、外部效果安全、不可变来源或恰好一次行为。</p><p>其可辩护结果更具体：受保护压缩可以在评测设置中保留重要路由表面并减少令牌，而不受保护的激进压缩会造成显著不对称失败。这使版本绑定的契约保留成为一项首要优化要求。</p><p>仍待解决的问题包括：哪些路由和入口不变量可静态验证；路由保留后需要多少行为抽样；如何把权限与副作用契约表达在加载路由旁；以及哪些证据应触发自动回滚。</p><p><strong>一手来源：</strong> <a href="https://arxiv.org/abs/2608.30785" target="_blank" rel="noreferrer">渐进加载技能压缩研究</a></p>',30))])}const k=t(o,[["render",p]]);export{g as __pageData,k as default};
